# -*- coding: utf-8 -*-
import collections, re

PATH='data/top/dataset_final.csv'
SEQS=[['bm','g','d','a'],['c','g','am','f'],['em','g'],['c','a7','dm','g7'],['gm','f'],['c','c7','f','fm']]
SEQS_STR=['BmGDA','CGAmF','EmG','CA7DmG7','GmF','CC7FFm']

def load():
    rows=[]
    f=open(PATH, encoding='utf-8')
    header=f.readline()
    for line in f:
        raw=line
        line=line.replace('"','').replace('NA','')[:-1]
        m=line.split(',')
        rows.append((raw.rstrip('\n'), m))
    return header.rstrip('\n'), rows

def limpa_cifra(raw_cifra):
    cifra=[]
    for m in raw_cifra:
        if m.strip()!='':
            if '|' in m:
                acorde=m.split('|')[0].split()[0]
                cifra.append(acorde)
            else:
                cifra += [t for t in m.split()]
    return cifra

# port of scripts/generate_data_set.py get_famosas
def get_famosas(acorde):
    seqs=['bm;g;d;a','c;g;am;f','em;g','c;a7;dm;g7','gm;f','c;c7;f;fm']
    out=[]
    for i in range(len(seqs)):
        s=seqs[i]
        acorde=acorde.lower()
        if s in acorde:
            achou=True
            for l in acorde.split(';'):
                tokens=s.split(';')
                if l not in tokens:
                    achou=False
                    break
            if achou:
                out.append(str(i))
    return out

header, rows = load()
print('HEADER:', header)
print('ROWS:', len(rows))
lens=collections.Counter(len(m) for _,m in rows)
print('FIELD COUNT DIST:', lens)

# generator tag reproduction on raw column 8 vs column 7
mismatch=0; examples=[]
seqdist=collections.Counter()
for raw,m in rows:
    if len(m)<9: continue
    cifra_raw=m[8]
    tags_csv=m[7]
    gen=''.join(get_famosas(cifra_raw)) if cifra_raw else ''
    if tags_csv!=gen:
        mismatch+=1
        if len(examples)<10: examples.append((tags_csv,gen,cifra_raw[:120]))
    seqdist[tags_csv]+=1
print('CSV SEQ_FAMOSA vs get_famosas(raw CIFRA) mismatches:', mismatch)
print('examples:', examples[:10])
print('SEQ_FAMOSA token dist (top 15):', seqdist.most_common(15))

# current backend matches per sequence
cur=[set() for _ in range(6)]
for raw,m in rows:
    if len(m)<9: continue
    seqs=m[7].split(';')
    for i in range(6):
        if str(i) in seqs:
            cur[i].add((m[0],m[1]))
print('CURRENT matches counts:', [len(s) for s in cur])

# chord list as main.py sees it
def cifra_list(m):
    return limpa_cifra(m[8].split(';')) if m[8]!='' else []

# candidate algorithms
def contiguous_full(seq, cifra):
    n=len(seq)
    return any(cifra[i:i+n]==seq for i in range(len(cifra)-n+1))

def contiguous_dedup(seq, cifra):
    # dedupe preserving first occurrence
    seen=set(); d=[]
    for c in cifra:
        if c not in seen:
            seen.add(c); d.append(c)
    n=len(seq)
    return any(d[i:i+n]==seq for i in range(len(d)-n+1))

def subset_any(seq, cifra):
    return set(seq).issubset(set(cifra))

def subsequence_ordered(seq, cifra):
    it=iter(cifra)
    return all(any(x==y for y in it) for x in seq)

# current tag semantics as understood: contiguous in raw full list AND all song chords in seq
def tag_semantics(seq, cifra):
    if not contiguous_full(seq, cifra): return False
    return set(cifra).issubset(set(seq))

cands={
 'contiguous_full':contiguous_full,
 'contiguous_dedup':contiguous_dedup,
 'subset_any':subset_any,
 'subsequence_ordered':subsequence_ordered,
 'tag_semantics':tag_semantics,
}
for name,fn in cands.items():
    res=[set() for _ in range(6)]
    for raw,m in rows:
        if len(m)<9: continue
        cif=cifra_list(m)
        for i,seq in enumerate(SEQS):
            if fn(seq,cif): res[i].add((m[0],m[1]))
    print(name, 'counts:', [len(r) for r in res],
          'eq_current:', [res[i]==cur[i] for i in range(6)],
          'extra_vs_current:', [len(res[i]-cur[i]) for i in range(6)],
          'missing_vs_current:', [len(cur[i]-res[i]) for i in range(6)])

# inspect current matches sample + their cifra
for i in range(6):
    print('--- seq',i,SEQS_STR[i],'count',len(cur[i]))
    for k in list(cur[i])[:3]:
        for raw,m in rows:
            if (m[0],m[1])==k:
                print('  ',k,'SEQ_FAMOSA=',repr(m[7]),'CIFRA=',m[8][:200])
                break
